#include <iostream>
#include <iomanip>
#include <string>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const unsigned long long MOD = 100000;
    unsigned long long n =
        (s[0] - '0') * 10000ULL +
        (s[2] - '0') * 1000ULL +
        (s[4] - '0') * 100ULL +
        (s[3] - '0') * 10ULL +
        (s[1] - '0');

    unsigned long long c = n;
    for (int i = 0; i < 4; ++i)
        n = n * c % MOD;

    cout << setfill('0') << setw(5) << n << '\n';
    return 0;
}

